package com.papaya.claims.workflow;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

/** Registry of pure effect planners; external work is dispatched only after commit. */
public final class EffectRegistry {
    private final Map<String, Function<WorkflowEvaluationContext, EffectIntent>> strategies;

    public EffectRegistry() {
        Map<String, Function<WorkflowEvaluationContext, EffectIntent>> registered = new LinkedHashMap<>();
        registered.put("notify_assessor_team", c -> plan("notify_assessor_team", "claimId", c.claim().id().toString()));
        registered.put("record_assessment_start", c -> plan("record_assessment_start", "occurredAt", c.now().toString()));
        registered.put("notify_member_approval", c -> plan("notify_member_approval", "claimId", c.claim().id().toString()));
        registered.put("create_payment_request", c -> new EffectIntent("create_payment_request", Map.of(
                "claimId", c.claim().id().toString(), "currency", c.claim().currency(),
                "amount", c.claim().facts().values().get("requestedAmount"))));
        registered.put("notify_member_rejection", c -> plan("notify_member_rejection", "reason", c.command().reason()));
        registered.put("notify_information_request", c -> plan("notify_information_request", "description", c.command().reason()));
        registered.put("reset_assessment_timer", c -> plan("reset_assessment_timer", "occurredAt", c.now().toString()));
        registered.put("trigger_payment_system", c -> plan("trigger_payment_system", "claimId", c.claim().id().toString()));
        registered.put("notify_member_payment_reference", c -> plan("notify_member_payment_reference", "reference", c.evidence().paymentReference()));
        registered.put("archive_claim", c -> plan("archive_claim", "claimId", c.claim().id().toString()));
        strategies = Map.copyOf(registered);
    }

    public Set<String> strategyIds() {
        return strategies.keySet();
    }

    public boolean supports(String id) {
        return strategies.containsKey(id);
    }

    public EffectIntent resolve(String id, WorkflowEvaluationContext context) {
        Function<WorkflowEvaluationContext, EffectIntent> strategy = strategies.get(id);
        if (strategy == null) throw new IllegalArgumentException("Unknown effect strategy: " + id);
        return strategy.apply(context);
    }

    private static EffectIntent plan(String id, String key, Object value) {
        return new EffectIntent(id, Map.of(key, value));
    }
}
package com.papaya.claims.workflow;

import java.math.BigDecimal;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.Set;
import java.util.function.Predicate;

public final class GuardEvaluator {
    private static final Pattern DOCUMENT_ID = Pattern.compile("[A-Za-z0-9][A-Za-z0-9._:-]{0,119}");
    private final Map<String, Predicate<WorkflowEvaluationContext>> strategies = Map.ofEntries(
            Map.entry("all_required_documents_present", this::allRequiredDocumentsPresent),
            Map.entry("assessor_assigned", c -> nonblank(c.claim().facts().values().get("assessorId"))),
            Map.entry("assessment_report_complete", c -> reportComplete(c.claim().facts().values().get("assessmentReport"))),
            Map.entry("amount_within_policy_limit", c -> amountWithin(
                    c.claim().facts().values().get("requestedAmount"), c.claim().policyLimit())),
            Map.entry("rejection_reason_present", c -> nonblank(c.command().reason())),
            Map.entry("information_description_present", c -> nonblank(c.command().reason())),
            Map.entry("new_information_received", this::newInformationReceived),
            Map.entry("payment_request_exists", c -> c.evidence().paymentRequestExists()),
            Map.entry("payment_confirmed", this::paymentConfirmed),
            Map.entry("appeal_period_expired_or_member_acknowledged", this::appealResolved));

    public Set<String> strategyIds() {
        return strategies.keySet();
    }

    public boolean passes(String id, WorkflowEvaluationContext c) {
        Predicate<WorkflowEvaluationContext> strategy = strategies.get(id);
        return strategy != null && strategy.test(c);
    }

    private boolean allRequiredDocumentsPresent(WorkflowEvaluationContext context) {
        return documentsValid(context.claim().facts().values());
    }

    private boolean newInformationReceived(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.lastInformationRequestedAt() != null && evidence.lastInformationReceivedAt() != null
                && evidence.lastInformationReceivedAt().isAfter(evidence.lastInformationRequestedAt());
    }

    private boolean paymentConfirmed(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.paymentRequestExists() && evidence.paymentConfirmedAt() != null
                && nonblank(evidence.paymentReference());
    }

    private boolean appealResolved(WorkflowEvaluationContext context) {
        WorkflowEvidence evidence = context.evidence();
        return evidence.rejectedAt() != null &&
                ((evidence.memberAcknowledgedRejectionAt() != null
                        && !evidence.memberAcknowledgedRejectionAt().isBefore(evidence.rejectedAt()))
                        || !context.now().isBefore(evidence.rejectedAt().plus(context.appealPeriod())));
    }
    private static boolean nonblank(Object o) { return o instanceof String s && !s.isBlank(); }
    private static boolean amountWithin(Object o, BigDecimal limit) {
        if (!(o instanceof BigDecimal b)) return false;
        return b.signum() >= 0 && b.scale() <= 2 && b.precision() - b.scale() <= 16 && b.compareTo(limit) <= 0;
    }
    private static boolean reportComplete(Object raw) {
        if (!(raw instanceof Map<?, ?> report)) return false;
        return Boolean.TRUE.equals(report.get("complete"));
    }
    private static boolean documentsValid(Map<String,Object> f) {
        Object raw=f.get("documents"); if (!(raw instanceof Map<?,?> docs) || docs.isEmpty()) return false;
        boolean hasRequired = false;
        for (var entry:docs.entrySet()) {
            if (!(entry.getKey() instanceof String id) || !DOCUMENT_ID.matcher(id).matches() || !(entry.getValue() instanceof Map<?,?> d)) return false;
            Object required = d.get("required"), present = d.get("present"), valid = d.get("valid");
            if (!(required instanceof Boolean) || !(present instanceof Boolean) || !(valid instanceof Boolean)) return false;
            if (Boolean.TRUE.equals(required)) {
                hasRequired = true;
                if (!Boolean.TRUE.equals(present) || !Boolean.TRUE.equals(valid)) return false;
            }
        }
        return hasRequired;
    }
}
package com.papaya.claims.workflow;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;
import java.io.IOException;
import java.io.InputStream;
import java.util.*;

public final class WorkflowConfigLoader {
    private static final Set<String> SUPPORTED_ROLES = Set.of("document_clerk", "team_lead", "assessor", "finance", "system");
    private final ObjectMapper mapper = new ObjectMapper(new YAMLFactory())
            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
    private final GuardEvaluator guardRegistry;
    private final EffectRegistry effectRegistry;

    public WorkflowConfigLoader() {
        this(new GuardEvaluator(), new EffectRegistry());
    }

    public WorkflowConfigLoader(GuardEvaluator guardRegistry, EffectRegistry effectRegistry) {
        this.guardRegistry = guardRegistry;
        this.effectRegistry = effectRegistry;
    }
    public WorkflowDefinition load(InputStream input) {
        try {
            Map<?,?> root = map(mapper.readValue(input, Map.class), "root");
            Map<?,?> w = map(root.get("workflow"), "workflow");
            Set<String> states = uniqueStrings(w.get("states"), "states");
            String initialState = text(w.get("initial-state"));
            if (!states.contains(initialState)) throw bad("Initial state is not declared");
            Map<String,String> guards = new LinkedHashMap<>();
            map(w.get("guard-catalog"),"guard-catalog").forEach((k,v)-> {
                String id = text(k);
                if (!guardRegistry.strategyIds().contains(id)) throw bad("Unknown guard strategy: " + id);
                guards.put(id, text(map(v,"guard").get("failure-message")));
            });
            Map<String,String> effects = new LinkedHashMap<>();
            map(w.get("effect-catalog"),"effect-catalog").forEach((k,v)-> {
                String id = text(k);
                if (!effectRegistry.supports(id)) throw bad("Unknown effect strategy: " + id);
                effects.put(id, text(v));
            });
            List<WorkflowDefinition.Transition> ts=new ArrayList<>(); Set<String> ids=new HashSet<>(); Set<String> edges=new HashSet<>();
            for(Object o:(List<?>)w.get("transitions")) { Map<?,?> t=map(o,"transition"); String id=text(t.get("id")), from=text(t.get("from")), to=text(t.get("to"));
                if(!ids.add(id)||!edges.add(from+"\u0000"+to)) throw bad("Duplicate transition id or edge"); if(!states.contains(from)||!states.contains(to)) throw bad("Dangling transition state");
                List<String> gs=List.copyOf(uniqueStrings(t.get("guards"),"guards")), es=List.copyOf(uniqueStrings(t.get("effects"),"effects")); if(!guards.keySet().containsAll(gs)||!effects.keySet().containsAll(es)) throw bad("Transition references unknown guard or effect");
                Set<String> roles = new LinkedHashSet<>(uniqueStrings(t.get("authorized-roles"), "authorized-roles"));
                if (roles.isEmpty() || !SUPPORTED_ROLES.containsAll(roles)) throw bad("Transition has missing or unknown roles");
                ts.add(new WorkflowDefinition.Transition(id,from,to,roles,gs,es)); }
            Map<?,?> cp=map(w.get("cycle-policy"),"cycle-policy");
            String cycleTransition = text(cp.get("transition-id"));
            String counter = text(cp.get("counter"));
            int max = positiveInteger(cp.get("maximum"), "cycle-policy.maximum");
            String cycleMessage = text(cp.get("error-message"));
            if (ts.stream().noneMatch(t -> t.id().equals(cycleTransition))) throw bad("Cycle policy transition is unknown");
            if (!"informationRequests".equals(counter)) throw bad("Unknown cycle counter: " + counter);
            if (w.containsKey("information-cycle-limit") && positiveInteger(w.get("information-cycle-limit"), "information-cycle-limit") != max)
                throw bad("Information cycle limit must match cycle policy maximum");
            return new WorkflowDefinition(text(w.get("version")),initialState,states,ts,guards,effects,
                    new WorkflowDefinition.CyclePolicy(cycleTransition,counter,max,cycleMessage));
        } catch(IOException|ClassCastException|NullPointerException ex) { throw new IllegalArgumentException("Invalid workflow configuration",ex); }
    }
    private static Map<?,?> map(Object x,String label){if(!(x instanceof Map<?,?> m))throw bad("Missing/invalid "+label);return m;}
    private static List<String> strings(Object x,String label){if(!(x instanceof List<?> l))throw bad("Missing/invalid "+label);return l.stream().map(WorkflowConfigLoader::text).toList();}
    private static Set<String> uniqueStrings(Object x, String label) {
        List<String> values = strings(x, label);
        Set<String> unique = new LinkedHashSet<>(values);
        if (unique.size() != values.size()) throw bad("Duplicate value in " + label);
        return unique;
    }
    private static int positiveInteger(Object value, String label) {
        if (!(value instanceof Number number)) throw bad("Missing/invalid " + label);
        long n = number.longValue();
        if (n <= 0 || n > Integer.MAX_VALUE || number.doubleValue() != n) throw bad("Invalid " + label);
        return (int) n;
    }
    private static String text(Object x){if(!(x instanceof String s)||s.isBlank())throw bad("Expected nonblank string");return s;}
    private static IllegalArgumentException bad(String m){return new IllegalArgumentException(m);}
}
package com.papaya.claims.workflow;

import java.util.List;

public final class WorkflowEngine {
    private final WorkflowDefinition definition;
    private final GuardEvaluator guards;
    private final EffectRegistry effects;

    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards) {
        this(definition, guards, new EffectRegistry());
    }

    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards, EffectRegistry effects) {
        this.definition = definition;
        this.guards = guards;
        this.effects = effects;
        if (!effects.strategyIds().containsAll(definition.effects().keySet()))
            throw new IllegalArgumentException("Workflow definition contains an unregistered effect strategy");
    }
    public List<WorkflowOption> available(WorkflowEvaluationContext c) {
        return definition.transitions().stream().filter(t -> t.from().equals(c.claim().state())).map(t -> {
            List<String> failures = failures(t, c);
            return new WorkflowOption(t.id(), t.from(), t.to(), t.roles(), failures.isEmpty(), failures, t.effects());
        }).toList();
    }
    public WorkflowDecision evaluate(WorkflowEvaluationContext c) {
        List<WorkflowOption> opts=available(c); WorkflowDefinition.Transition t=definition.transitions().stream().filter(x->x.from().equals(c.claim().state())&&x.to().equals(c.command().targetState())).findFirst().orElse(null);
        if(t==null) return WorkflowDecision.denied("INVALID_EDGE","No transition exists from current state to requested state",opts);
        if(!t.roles().stream().anyMatch(c.actor()::hasRole)) return WorkflowDecision.denied("ROLE_FORBIDDEN","Actor is not authorized for this transition",opts);
        for(String g:t.guards()) if(!guards.passes(g,c)) return WorkflowDecision.denied(g.toUpperCase(java.util.Locale.ROOT),definition.guardMessages().get(g),opts);
        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
        if(t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter())>=cycle.maximum())
            return WorkflowDecision.denied("CYCLE_LIMIT",cycle.errorMessage(),opts);
        List<EffectIntent> plannedEffects = t.effects().stream().map(id -> effects.resolve(id, c)).toList();
        return new WorkflowDecision(true,t.id(),t.from(),t.to(),null,null,plannedEffects,opts);
    }
    private List<String> failures(WorkflowDefinition.Transition t, WorkflowEvaluationContext c) {
        List<String> failures = new java.util.ArrayList<>();
        if (t.roles().stream().noneMatch(c.actor()::hasRole)) failures.add("ROLE_FORBIDDEN");
        for (String guard : t.guards()) if (!guards.passes(guard, c)) failures.add(guard);
        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
        if (t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter()) >= cycle.maximum()) failures.add("CYCLE_LIMIT");
        return List.copyOf(failures);
    }
}
package com.papaya.claims.config;

import com.papaya.claims.workflow.GuardEvaluator;
import com.papaya.claims.workflow.EffectRegistry;
import com.papaya.claims.workflow.WorkflowConfigLoader;
import com.papaya.claims.workflow.WorkflowDefinition;
import com.papaya.claims.workflow.WorkflowEngine;
import java.io.IOException;
import java.io.InputStream;
import java.time.Clock;
import java.time.Duration;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.Resource;
import org.springframework.core.io.ResourceLoader;

@Configuration
public class WorkflowConfiguration {
    @Bean
    GuardEvaluator guardEvaluator() {
        return new GuardEvaluator();
    }

    @Bean
    EffectRegistry effectRegistry() {
        return new EffectRegistry();
    }

    @Bean
    WorkflowDefinition workflowDefinition(
            ResourceLoader resourceLoader,
            @Value("${claims.workflow.definition:classpath:config/workflow.yml}") String location,
            GuardEvaluator guards,
            EffectRegistry effects) {
        Resource resource = resourceLoader.getResource(location);
        try (InputStream input = resource.getInputStream()) {
            return new WorkflowConfigLoader(guards, effects).load(input);
        } catch (IOException exception) {
            throw new IllegalStateException("Unable to load workflow definition from " + location, exception);
        }
    }

    @Bean
    WorkflowEngine workflowEngine(WorkflowDefinition definition, GuardEvaluator guards, EffectRegistry effects) {
        return new WorkflowEngine(definition, guards, effects);
    }

    @Bean
    Clock applicationClock() {
        return Clock.systemUTC();
    }

    @Bean
    Duration appealPeriod(@Value("${claims.workflow.appeal-period:P30D}") String configured) {
        Duration duration = Duration.parse(configured);
        if (duration.isNegative() || duration.isZero()) {
            throw new IllegalArgumentException("claims.workflow.appeal-period must be positive");
        }
        return duration;
    }
}

package com.papaya.claims.workflow;

import java.util.List;
import java.util.Map;
import java.util.Set;

public record WorkflowDefinition(String version, String initialState, Set<String> states,
        List<Transition> transitions, Map<String,String> guardMessages, Map<String,String> effects,
        CyclePolicy cyclePolicy) {
    public WorkflowDefinition {
        states = Set.copyOf(states);
        transitions = List.copyOf(transitions);
        guardMessages = Map.copyOf(guardMessages);
        effects = Map.copyOf(effects);
    }
    public record CyclePolicy(String transitionId, String counter, int maximum, String errorMessage) { }
    public record Transition(String id, String from, String to, Set<String> roles, List<String> guards, List<String> effects) {
        public Transition { roles=Set.copyOf(roles); guards=List.copyOf(guards); effects=List.copyOf(effects); }
    }
}
package com.papaya.claims.workflow;

import java.time.Instant;

/** Trusted server supplied evidence. Never construct this record from client supplied facts. */
public record WorkflowEvidence(int informationRequests, Instant lastInformationRequestedAt,
        Instant lastInformationReceivedAt, Instant assessmentStartedAt, Instant rejectedAt,
        Instant memberAcknowledgedRejectionAt, boolean paymentRequestExists, String paymentReference,
        Instant paymentConfirmedAt) {
    public WorkflowEvidence {
        lastInformationRequestedAt = micros(lastInformationRequestedAt);
        lastInformationReceivedAt = micros(lastInformationReceivedAt);
        assessmentStartedAt = micros(assessmentStartedAt);
        paymentConfirmedAt = micros(paymentConfirmedAt);
        rejectedAt = micros(rejectedAt);
        memberAcknowledgedRejectionAt = micros(memberAcknowledgedRejectionAt);
        if (informationRequests < 0) throw new IllegalArgumentException("Cycle count cannot be negative");
    }
    public int counterValue(String counter) {
        if ("informationRequests".equals(counter)) return informationRequests;
        throw new IllegalArgumentException("Unsupported cycle counter: " + counter);
    }
    private static Instant micros(Instant value) { return value == null ? null : value.truncatedTo(java.time.temporal.ChronoUnit.MICROS); }
    public static WorkflowEvidence empty() { return new WorkflowEvidence(0,null,null,null,null,null,false,null,null); }
}
package com.papaya.claims.workflow;

import java.util.Map;
import java.util.Objects;

/** Pure effect plan. The application service persists it to the outbox in the claim transaction. */
public record EffectIntent(String id, Map<String, Object> payload) {
    public EffectIntent {
        if (id == null || id.isBlank()) throw new IllegalArgumentException("Effect id is required");
        payload = Map.copyOf(Objects.requireNonNull(payload, "payload"));
    }
}
package com.papaya.claims.workflow;

import java.util.List;

public record WorkflowDecision(boolean allowed, String transitionId, String from, String to,
                               String failureCode, String failureMessage, List<EffectIntent> effects,
                               List<WorkflowOption> availableTransitions) {
    public WorkflowDecision { effects = List.copyOf(effects); availableTransitions = List.copyOf(availableTransitions); }
    public static WorkflowDecision denied(String code, String message, List<WorkflowOption> available) {
        return new WorkflowDecision(false, null, null, null, code, message, List.of(), available);
    }
}
